const D = { energy:.6, density:.5, scale:1, speed:1, hue:118, boughs:3, x:.5, y:.5, style:'humid_plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.4,2.2);
const NB = Math.round(cl(P.boughs,1,3)), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29) + .38*Math.sin(T*.149);
const breeze = (.28 + .9*EN)*gust + A.lowmid*.85 + K.pulse*.2*K.intensity;

// ---- style ---------------------------------------------------------------
const H = P.hue;
let mode;
if (sty === 'cyanotype') mode = 1; else if (sty === 'xray') mode = 2;
else if (sty === 'nocturne') mode = 3; else mode = 0;

// ---- humid gloom + a drifting canopy dapple (a moving luminance field) ---
const bgKey = [width,height,sd,sty,H].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(560, Math.max(220, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke();
  for (let y=0;y<bh;y++){ const v = y/bh;
    if (mode === 1) g.fill(214, 82 - v*6, 32 - v*12);
    else if (mode === 2) g.fill(196, 42, 16 - v*4);
    else if (mode === 3) g.fill(28, 44, 17 - v*7);
    else g.fill(H - 26 + v*10, 22 + v*10, 60 - v*26);
    g.rect(0, y, bw, 1.2); }
  for (let i=0;i<2400;i++){ g.fill(0, 0, mode===0 ? 40 : 92, 4 + fr(i*3.9)*8);
    g.rect(fr(i*2.7)*bw, fr(i*6.3+2)*bh, 1.5, 1.5); }
  g.pop();
  // the dapple is a SEPARATE, oversized buffer that drifts -> whole-frame slow motion
  const dw = 300, dh = Math.max(1, Math.round(dw*height/Math.max(1,width)));
  if (S.dp && S.dp.remove) S.dp.remove();
  const d2 = createGraphics(dw, dh);
  S.dp = d2; d2.colorMode(HSB, 360, 100, 100, 100);
  d2.push(); d2.clear(); d2.noStroke();
  for (let i=0;i<120;i++){                                   // soft light pools through the canopy
    const px2 = fr(i*5.3)*dw, py2 = fr(i*7.1)*dh, r = dw*(.03 + fr(i*2.3)*.13);
    for (let k=5;k>0;k--) { d2.fill(mode===1?208:(mode===3?42:52), mode===1?20:26, 100, 2.4);
      d2.ellipse(px2, py2, r*k*.42, r*k*.36); }
  }
  d2.pop();
}
image(S.g, 0, 0, width, height);
blendMode(mode === 3 ? ADD : SCREEN);
const dox = (Math.sin(T*.037) + .3*Math.sin(T*.0911 + 2.1))*width*.06;
const doy = (Math.cos(T*.029) + .3*Math.sin(T*.0713))*height*.05;
tint(0, 0, 100, mode===2 ? 22 : 40);
image(S.dp, -width*.08 + dox, -height*.08 + doy, width*1.16, height*1.16);
noTint(); blendMode(BLEND);

// ---- boughs (host surfaces the epiphytes compete for) --------------------
const bough = k => {                                        // k = 0 far .. NB-1 near
  const z = NB === 1 ? 1 : .3 + .7*(k/(NB-1));
  const j = k*13.7 + 3;
  return { z: z,
    y: (.22 + .3*(1 - z) + (k===NB-1 ? .42 : 0) + (fr(j*1.3)-.5)*.06 + (P.y-.5)*.5),
    tilt: (fr(j*2.7)-.5)*.34, bow: (fr(j*3.9)-.5)*.16, ph: fr(j*5.1)*6.28 };
};
const boughY = (b, xn) => (b.y + b.tilt*(xn-.5) + b.bow*Math.sin((xn-.1)*3.4 + b.ph))*height
  + breeze*u*.004*b.z*Math.sin(T*.71 + b.ph);
const boughR = b => u*(.017 + .026*b.z)*SC;

// ---- epiphyte sites: each site walks the successional sequence ----------
// gen 0 crust -> 1 moss cushion -> 2 tillandsia/bromeliad rosette -> 3 orchid w/ pseudobulbs
const NMAX = 16;
const reseed = (s, hard) => {
  const j = s.id*23.7 + (s.rr = (s.rr||0)+1)*9.1;
  // the site establishes where the propagule rain actually lands -> clusters on the P.x focus
  if (hard) { s.gen = 0; s.bg = (s.id % Math.max(1,NB));
    s.xn = cl(P.x + (fr(j*1.7) + fr(j*2.9) - 1)*.62, .04, .96); }
  else s.gen = Math.min(3, (s.gen||0) + 1);                 // succession: the site matures
  s.age = 0;
  s.life = 22 + fr(j*2.3)*16 + s.gen*7;
  s.hold = 8 + fr(j*3.1)*10;
  s.sen = 8 + fr(j*4.3)*8;
  s.dead = 0;
  s.sz = .72 + fr(j*5.7)*.6;
  s.ph = fr(j*6.9)*6.28;
  s.nl = 6 + ((fr(j*7.3)*3)|0);
  s.hj = (fr(j*8.1)-.5)*40;
  s.side = fr(j*9.3) < .5 ? -1 : 1;
  s.roots = 1 + ((fr(j*11.7)*2.6)|0);
};
const adv = (s, d) => {
  s.age += d;
  const tot = s.life + s.hold + s.sen;
  if (s.age > tot) {
    if (s.gen >= 3) reseed(s, true);                        // the whole site falls and starts over
    else reseed(s, false);
  }
};
if (!S.si || S.si.length !== NMAX || S.szKey !== width+'x'+height+sd+NB) {
  S.szKey = width+'x'+height+sd+NB; S.si = [];
  for (let i=0;i<NMAX;i++){ const s = { id:i }; reseed(s, true);
    const w = fr(i*15.1)*140; for (let q=0;q<Math.round(w*8);q++) adv(s, 1/8);
    S.si.push(s); }
}
for (let i=0;i<NMAX;i++) adv(S.si[i], dt*SP*(.6 + .8*EN)*(.7 + .5*K.intensity));

// ---- draw boughs ---------------------------------------------------------
strokeCap(ROUND); strokeJoin(ROUND);
const BS = [];
for (let k=0;k<NB;k++) BS.push(bough(k));
for (let k=0;k<NB;k++) {
  const b = BS[k], r = boughR(b), haze = .32 + .68*b.z;
  noFill();
  if (mode === 1) stroke(216, 66 - b.z*18, 14 + b.z*8, 96*AL);
  else if (mode === 2) stroke(200, 26, 34*haze, 46*AL);
  else if (mode === 3) stroke(26, 40, 8 + 12*b.z, 96*AL);
  else stroke(26, 30 + b.z*10, (16 + 14*b.z), 92*AL*(.5 + .5*haze));
  strokeWeight(r*2);
  beginShape();
  for (let q=0;q<=12;q++){ const xn = q/12 - .06; vertex(xn*width*1.12, boughY(b, xn)); }
  endShape();
  if (mode !== 2) {                                          // bark fissures — texture over flat fill
    strokeWeight(Math.max(.5, r*.11));
    for (let q=0;q<22;q++){
      const xn = fr(k*7.7 + q*2.1)*1.05 - .03, off = (fr(k*3.3 + q*5.7)-.5)*1.7;
      const y0 = boughY(b, xn) + off*r, ln = r*(.5 + fr(k*9.1+q)*1.6);
      if (mode === 1) stroke(216, 50, 26, 40*AL);
      else if (mode === 3) stroke(30, 34, 22 + 14*b.z, 34*AL);
      else stroke(28, 26, 30 + 18*b.z, 34*AL);
      line(xn*width*1.12, y0, xn*width*1.12 + ln, y0 + ln*.16*(q%2?1:-1));
    }
    stroke(mode===1?214:(mode===3?40:36), mode===1?12:26, mode===1?60:(38 + 22*b.z), 34*AL);
    strokeWeight(Math.max(.6, r*.16)); beginShape();        // top-lit rim
    for (let q=0;q<=12;q++){ const xn = q/12 - .06; vertex(xn*width*1.12, boughY(b, xn) - r*.72); }
    endShape();
  }
}

// ---- epiphytes -----------------------------------------------------------
const nDraw = Math.max(2, Math.round(3 + DN*13));
for (let n=0;n<nDraw;n++) {
  const s = S.si[n]; if (!s) continue;
  const b = BS[Math.min(s.bg, NB-1)]; if (!b) continue;
  const gx = (s.xn - .06)*width*1.12, gy = boughY(b, s.xn) - boughR(b)*.55;
  const grow = cl(s.age/Math.max(1,s.life), 0, 1);
  const gr = grow*grow*(3 - 2*grow);
  const ph2 = s.life + s.hold;
  const dry = s.age > ph2 ? cl((s.age - ph2)/s.sen, 0, 1) : 0;
  const fade = 1 - dry*.55;
  const R = u*.05*SC*s.sz*b.z*(.25 + .75*gr);
  const hh = ((P.hue + s.hj + dry*30) % 360 + 360) % 360;
  const ss = (54 - dry*30)*(.5 + .5*b.z), bb = (32 + 24*b.z)*(1 - dry*.2) + dry*22;
  const swy = breeze*u*.008*b.z*(.5 + .8*Math.sin(T*1.23 + s.ph));
  const alp = AL*fade*(.35 + .65*b.z);
  push(); translate(gx + swy*.4, gy);
  if (mode === 2) blendMode(ADD);
  // --- gen 0: pioneer crust
  if (s.gen === 0) {
    noStroke();
    for (let k=0;k<7;k++){
      const a2 = fr(s.id*3.1 + k*7.7)*6.28, rr = R*(.35 + fr(s.id*5.3+k)*.75)*1.2;
      if (mode === 1) fill(214, 24, 82, 40*alp);
      else if (mode === 2) fill(hh, 40, 40, 12*alp);
      else fill(hh + 18, ss*.5, bb*.9, 46*alp);
      ellipse(Math.cos(a2)*R*.5, Math.sin(a2)*R*.22, rr, rr*.5);
    }
  }
  // --- gen 1: moss cushion + short shoots
  if (s.gen === 1) {
    noStroke();
    if (mode === 1) fill(214, 16, 90, 66*alp); else if (mode === 2) fill(hh, 46, 34, 15*alp);
    else fill(hh, ss, bb*.85, 76*alp);
    ellipse(0, -R*.12, R*1.5, R*.72);
    noFill(); strokeWeight(Math.max(.5, R*.05));
    if (mode === 1) stroke(214, 10, 96, 50*alp); else if (mode === 2) stroke(hh, 40, 66, 16*alp);
    else stroke(hh, ss + 10, bb + 16, 56*alp);
    for (let k=0;k<9;k++){
      const a2 = -Math.PI*.5 + (fr(s.id*2.7+k*3.3)-.5)*2.2;
      const L = R*(.3 + fr(s.id*4.1+k)*.5)*(1 - dry*.35);
      const w2 = breeze*R*.12*(.4 + Math.sin(T*2.3 + k + s.ph));
      line((k/8-.5)*R*1.2, -R*.2, (k/8-.5)*R*1.2 + Math.cos(a2)*L + w2, -R*.2 + Math.sin(a2)*L);
    }
  }
  // --- gen 2: tillandsia / bromeliad rosette
  if (s.gen === 2) {
    for (let k=0;k<s.nl;k++){
      const a2 = -Math.PI*.5 + ((k + .5)/s.nl - .5)*2.7 + s.side*.16;
      const fl = Math.sin(T*(1.5 + (k%4)*.31) + s.ph + k)*(.05 + .17*EN);
      const L = R*(1.5 + fr(s.id*6.1+k)*.7)*(1 - dry*.2);
      const arc = .55 + dry*.5;                             // straps recurve as they dry
      push(); rotate(a2 + fl + swy*.006);
      if (mode === 1) { noStroke(); fill(214, 8 + k*.6, 94 - k*1.2, 82*alp); }
      else if (mode === 2) { noStroke(); fill(hh, 48, 40, 16*alp); }
      else if (mode === 3) { noStroke(); fill(hh, ss*.8, (10 + bb*.9)*(1 - k*.02), 92*alp); }
      else { stroke(24, 46, 18, 44*alp); strokeWeight(Math.max(.4, R*.035));
        fill(hh + k*1.4, ss + 8, bb + (k%2?7:0), 90*alp); }
      beginShape(); vertex(0, 0);
      bezierVertex(R*.28, -R*.12*arc, L*.62, -R*.16*arc, L, -R*.05*arc);
      bezierVertex(L*.62, R*.13*arc, R*.28, R*.16*arc, 0, 0);
      endShape(CLOSE);
      if (mode === 0) { stroke(hh, ss*.4, bb + 26, 40*alp); strokeWeight(Math.max(.35, R*.02));
        line(R*.1, 0, L*.9, -R*.03*arc); }
      pop();
    }
  }
  // --- gen 3: orchid — pseudobulbs + an arching flower spike
  if (s.gen === 3) {
    noStroke();
    for (let k=0;k<3;k++){                                   // pseudobulbs
      if (mode === 1) fill(214, 12, 92, 84*alp); else if (mode === 2) fill(hh, 44, 44, 16*alp);
      else fill(hh - 8, ss - 10, bb + 10 - dry*8, 92*alp);
      ellipse((k-1)*R*.6, -R*.35, R*.5, R*.95);
    }
    for (let k=0;k<4;k++){                                   // strap leaves
      const a2 = -Math.PI*.5 + (k/3 - .5)*1.9;
      const L = R*(1.5 + fr(s.id*3.7+k)*.5)*(1 - dry*.25);
      const fl = Math.sin(T*(1.3 + k*.27) + s.ph)*(.04 + .14*EN);
      push(); rotate(a2 + fl);
      if (mode === 1) fill(214, 10, 90, 80*alp); else if (mode === 2) fill(hh, 46, 38, 15*alp);
      else fill(hh + 4, ss, bb, 88*alp);
      beginShape(); vertex(0, -R*.5);
      bezierVertex(R*.3, -R*.7, L*.7, -R*.66, L, -R*.5);
      bezierVertex(L*.7, -R*.34, R*.3, -R*.3, 0, -R*.5);
      endShape(CLOSE); pop();
    }
    const spk = cl((s.age - s.life*.7)/12, 0, 1)*(1 - dry);  // the arching inflorescence
    if (spk > .02) {
      noFill(); strokeWeight(Math.max(.7, R*.07));
      if (mode === 1) stroke(214, 14, 86, 70*alp); else if (mode === 2) stroke(hh, 40, 62, 18*alp);
      else stroke(hh - 14, ss - 8, bb + 6, 76*alp);
      const SL = R*3.1*spk, sw2 = breeze*R*.5*(.4 + .7*Math.sin(T*.93 + s.ph));
      beginShape();
      for (let q=0;q<=7;q++){ const v = q/7;
        vertex(s.side*(v*SL*.75 + sw2*v*v), -R*.7 - SL*(v*.72 - v*v*.3)); }
      endShape();
      noStroke();
      for (let q=1;q<=4;q++){ const v = q/4.4;
        const fx = s.side*(v*SL*.75 + sw2*v*v), fy = -R*.7 - SL*(v*.72 - v*v*.3);
        if (mode === 1) fill(214, 2, 100, 88*alp); else if (mode === 2) fill(hh + 180, 50, 70, 22*alp);
        else fill((hh + 178) % 360, 40 + 20*spk, 76 + 14*b.z, 92*alp);
        ellipse(fx, fy, R*.34*spk, R*.28*spk); }
    }
  }
  // --- aerial roots dangling off the bough — the piece's motion floor
  if (s.gen >= 2) {
    noFill();
    if (mode === 1) stroke(214, 12, 84, 56*alp); else if (mode === 2) stroke(hh + 20, 24, 66, 16*alp);
    else stroke(38, 16 + dry*10, 40 + 20*b.z, 52*alp);
    strokeWeight(Math.max(.5, R*.055));
    for (let k=0;k<s.roots;k++){
      const rp = s.ph + k*2.3;
      const RL = u*.10*SC*b.z*cl((s.age - s.life*.4)/22, 0, 1.35)*(.6 + fr(s.id*7.1+k)*.8);
      const rx = (k - (s.roots-1)*.5)*R*.5;
      beginShape();
      for (let q=0;q<=6;q++){ const v = q/6;
        vertex(rx + breeze*u*.022*b.z*v*v*(.4 + .7*Math.sin(T*(.97 + k*.21) + rp))
               + Math.sin(T*1.7 + v*3.1 + rp)*u*.004*v*(.4+EN),
               R*.2 + RL*v); }
      endShape();
    }
  }
  blendMode(BLEND);
  pop();
}
// ---- windborne propagules hunting for a free site ------------------------
const nS = Math.round(10 + DN*26);
noStroke();
for (let k=0;k<nS;k++) {
  const ph = fr(k*4.7)*6.28;
  const dv = ((T*(.021 + fr(k*6.1)*.03) + fr(k*8.3)) % 1);
  // ...and the rain itself converges on that focus, live
  const conv = (P.x - .5)*2*Math.sin(dv*Math.PI)*.34;
  const sx = ((dv*1.14 - .07) + conv)*width + breeze*u*.03;
  const syy = (fr(k*2.9)*1.05 - .02)*height + Math.sin(T*(.8 + fr(k*3.1)) + ph)*u*.03;
  if (mode === 1) fill(214, 4, 100, 30*AL); else if (mode === 2) fill(H, 20, 90, 12*AL);
  else fill(mode===3 ? 44 : 52, 12, 88, 26*AL);
  const r = u*.0035*SC*(.5 + fr(k*9.7));
  ellipse(sx, syy, r*2, r*2);
  if (mode !== 2) {                                          // the plumose pappus that carries it
    stroke(mode===1?214:50, 8, 92, 12*AL); strokeWeight(.6);
    for (let q=0;q<4;q++){ const a2 = ph + q*1.57 + T*.3;
      line(sx, syy, sx + Math.cos(a2)*r*3.4, syy + Math.sin(a2)*r*3.4); }
    noStroke();
  }
}
blendMode(BLEND);
